var e={name:"xcbeautify",description:"A tool to format `swift` and `xcodebuild` command output",options:[{name:["-q","--quiet"],description:"Only print tasks that have warnings or errors"},{name:["--quieter","-qq"],description:"Only print tasks that have errors"},{name:"--preserve-unbeautified",description:"Preserves unbeautified output lines"},{name:"--is-ci",description:"Print test result too under quiet/quieter flag"},{name:"--disable-colored-output",description:"Disable the colored output"},{name:"--disable-logging",description:"Suppress the xcbeautify information table on start"},{name:"--renderer",description:"Specify a renderer to format raw xcodebuild output",args:{name:"renderer",suggestions:["terminal","github-actions","teamcity","azure-devops-pipelines"],default:"terminal"}},{name:"--report",description:"Generate the specified reports",args:{name:"report",suggestions:["junit"]},isRepeatable:!0},{name:"--report-path",description:"The path to use when generating reports",args:{name:"report-path",template:"folders",default:"build/reports"}},{name:"--junit-report-filename",description:"The name of the JUnit report file",args:{name:"filename",default:"junit.xml"}},{name:"--version",description:"Show the version"},{name:["-h","--help"],description:"Show help information"}]},t=e;export{t as default};
